func:
msg.payload = {
    ok: 1,
    msg: "Thành công",
    students: [
        {
            id: 1,
            name: "Nguyễn Văn An",
            class: "K59 KMT.K01",
            score: 8.5
        },
        {
            id: 2,
            name: "Trần Thị Bình",
            class: "K59 KMT.K01",
            score: 7.5
        },
        {
            id: 3,
            name: "David",
            class: "K59 KMT.K02",
            score: 9.0
        }
    ]
};
msg.headers = {
    "Content-Type": "application/json; charset=utf-8"
};
return msg;

const scoreParam = msg.req.query.score;

// Validation: thiếu score
if (scoreParam === undefined || scoreParam === '') {
    msg.statusCode = 400;
    msg.payload = {
        ok: 0,
        msg: "Thiếu tham số score",
        error: "MISSING_SCORE"
    };
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
    return msg;
}

// Validation: không phải số
const score = parseFloat(scoreParam);
if (isNaN(score)) {
    msg.statusCode = 400;
    msg.payload = {
        ok: 0,
        msg: "Score phải là một số",
        error: "INVALID_SCORE"
    };
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
    return msg;
}

// Validation: score < 0
if (score < 0) {
    msg.statusCode = 400;
    msg.payload = {
        ok: 0,
        msg: "Score không được nhỏ hơn 0",
        error: "SCORE_TOO_LOW"
    };
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
    return msg;
}

// Validation: score > 10
if (score > 10) {
    msg.statusCode = 400;
    msg.payload = {
        ok: 0,
        msg: "Score không được lớn hơn 10",
        error: "SCORE_TOO_HIGH"
    };
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
    return msg;
}

// Thuật toán xếp loại
let rank;
if (score >= 8.5) {
    rank = "Giỏi";
} else if (score >= 7.0) {
    rank = "Khá";
} else if (score >= 5.0) {
    rank = "Trung bình";
} else {
    rank = "Yếu";
}

msg.payload = {
    ok: 1,
    msg: "Thành công",
    score: score,
    rank: rank
};
msg.headers = {
    "Content-Type": "application/json; charset=utf-8"
};
msg.statusCode = 200;
return msg;
